from typing import List, Union

class SquareEvenFinder:
    """
    Class to find the squares of even numbers in a given list.
    """

    def __init__(self):
        pass

    def __call__(self, numbers_list: Union[List[int], None] = None) -> List[int]:
        if numbers_list is None:
            raise ValueError("List of numbers is required.")

        if not numbers_list:
            raise ValueError("List cannot be empty.")

        squares_of_evens = []
        for num in numbers_list:
            if num % 2 == 0:
                squares_of_evens.append(num ** 2)

        return squares_of_evens
