import threading

class ResourcePool:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls, *args, **kwargs):
        with cls._lock:
            if not cls._instance:
                cls._instance = super(ResourcePool, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def __init__(self):
        self.resources = []
        self.lock = threading.Lock()

    def acquire(self):
        with self.lock:
            if self.resources:
                return self.resources.pop()
            else:
                return self.create_resource()

    def release(self, resource):
        with self.lock:
            self.resources.append(resource)

    def create_resource(self):
        # Simulate resource creation
        return f"Resource-{len(self.resources) + 1}"

    def __enter__(self):
        return self.acquire()

    def __exit__(self, exc_type, exc_value, traceback):
        self.release(exc_type)

# Usage example
if __name__ == "__main__":
    pool = ResourcePool()

    def worker():
        with pool as resource:
            print(f"Working with {resource}")

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
```

```python
def filter_and_convert_to_float(input_list):
    positive_floats = []
    for item in input_list:
        try:
            number = float(item)
            if number > 0:
                positive_floats.append(number)
        except ValueError:
            print(f"Warning: '{item}' cannot be converted to a float and will be skipped.")
    return positive_floats
```

